set -euo pipefail; B=$HOME/.cache/in-the-loop/spring-java-data; export GRADLE_USER_HOME=$B/gradle-home TMPDIR=$B/tmp; mkdir -p $B/tmp $B/logs $B/artifacts; 
summarize() {  # summarize DIR: count JUnit XML results and name the failures
python3 -I - "$1" <<'PY'
import glob, sys, xml.etree.ElementTree as E
t = f = e = s = 0; bad = []
for p in sorted(glob.glob(sys.argv[1] + "/TEST-*.xml")):
    r = E.parse(p).getroot()
    t += int(r.get("tests", 0)); f += int(r.get("failures", 0)); e += int(r.get("errors", 0)); s += int(r.get("skipped", 0))
    for c in r.iter("testcase"):
        if c.find("failure") is not None or c.find("error") is not None:
            bad.append(r.get("name").rsplit(".", 1)[-1] + "#" + c.get("name"))
print(f"junit tests={t} failures={f} errors={e} skipped={s}")
for b in bad: print("junit failed", b)
PY
}
